    /**
     * Method to retrieve the Person via an FindPersonQuery
     * @return 	query	FindPersonQuery
     */
    @SuppressWarnings("unused")
    public Person find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Person - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Persons
     *
     * @param	query	FindAllPersonQuery 
     * @return 	List<Person> 
     */
    @SuppressWarnings("unused")
    public List<Person> findAll( FindAllPersonQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Person - {0}", exc.getMessage() );
    	}
    	return null;
    }


